from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    fill = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def mode_and_frac(seq):
        color, count = Counter(seq).most_common(1)[0]
        return color, count / len(seq)

    row_modes = [mode_and_frac(row) for row in grid]
    col_modes = [mode_and_frac([grid[r][c] for r in range(h)]) for c in range(w)]
    rlines = [i for i, (color, frac) in enumerate(row_modes) if color != fill and frac >= .65]
    clines = [i for i, (color, frac) in enumerate(col_modes) if color != fill and frac >= .65]
    line_colors = {row_modes[i][0] for i in rlines} | {col_modes[i][0] for i in clines}

    # Adjacent grid-line pairs enclose output cells when their four corners
    # carry the same marker color. Crop to the extent of the marked cells.
    marked = {}
    for ri in range(len(rlines) - 1):
        r0, r1 = rlines[ri], rlines[ri + 1]
        for ci in range(len(clines) - 1):
            c0, c1 = clines[ci], clines[ci + 1]
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            if corners[0] not in line_colors and all(v == corners[0] for v in corners):
                marked[(ri, ci)] = corners[0]
    if not marked:
        return [[fill]]
    r0 = min(r for r, c in marked); r1 = max(r for r, c in marked)
    c0 = min(c for r, c in marked); c1 = max(c for r, c in marked)
    return [[marked.get((r, c), fill) for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]

